def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    concept_path = OUT / "concepts.starter.jsonl"
    edge_path = OUT / "relationships.starter.jsonl"
    with concept_path.open("w", encoding="utf-8", newline="\n") as stream:
        for identifier, (label, summary, aliases) in sorted(C.items()):
            volume = 1 if identifier <= 1000 else 2
            entry = {
                "id": identifier,
                "label": label,
                "summary": summary,
                "domains": ["societal_inventory"],
                "aliases": aliases.split(),
                "original_text": None,
                "source": {"kind": "conversation_inventory_reference", "volume": volume,
                           "entry_id": identifier, "extraction_method": "manual_starter_summary"},
                "status": "seed_summary_pending_transcription",
            }
            stream.write(json.dumps(entry, ensure_ascii=False, sort_keys=True) + "\n")
    if len({(a,b,t) for a,b,t,r in RELATIONSHIPS}) != len(RELATIONSHIPS):
        raise ValueError("Repeated relationship")
    for a,b,t,r in RELATIONSHIPS:
        if a not in C or b not in C:
            raise ValueError(f"Missing referenced concept: {a} or {b}")
    with edge_path.open("w", encoding="utf-8", newline="\n") as stream:
        for a,b,relation,rationale in sorted(RELATIONSHIPS):
            edge = {"source":a,"target":b,"type":relation,"rationale":rationale,
                    "provenance":"curator_hypothesis_not_empirically_verified"}
            stream.write(json.dumps(edge, ensure_ascii=False, sort_keys=True) + "\n")
    with (OUT / "rules.v1.json").open("w",encoding="utf-8",newline="\n") as stream:
        json.dump(RULES, stream, ensure_ascii=False, indent=2, sort_keys=True)
        stream.write("\n")
    print(f"Built {len(C)} starter concepts, {len(RELATIONSHIPS)} hypothesis links, {len(RULES)} interpretation rules")


if __name__ == "__main__":
    main()
